namespace Challenge;public record Order(string Id,string Owner,string Status,string Note);public sealed class Orders(Dictionary<string,Order> data){Order? Owned(string actor,string id)=>data.TryGetValue(id,out var o)&&o.Owner==actor?o:null;public Order? Get(string actor,string id)=>Owned(actor,id);public string Update(string actor,string id,string note){var o=Owned(actor,id);if(o is null)return "NotFound";data[id]=o with{Note=note};return "Ok";}public string Cancel(string actor,string id){var o=Owned(actor,id);if(o is null)return "NotFound";data[id]=o with{Status="Cancelled"};return "Ok";}}
